import{_ as e,o as l,c as a,a4 as i}from"./chunks/framework.2-Vke5-n.js";const r="/arch-guidelines/assets/abstract.drawio.DqDgH1vP.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"I/F設計ガイドライン","tagline":"I/F Design Guidelines","actions":[{"theme":"brand","text":"I/F設計ガイドライン","link":"./if_guidelines.md"}]}},"headers":[],"relativePath":"documents/forIF/index.md","filePath":"documents/forIF/index.md"}'),s={name:"documents/forIF/index.md"};function d(n,t,o,c,h,u){return l(),a("div",null,[...t[0]||(t[0]=[i('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>I/Fとはインタフェースの略で、ここではシステム間のデータ連携における、システムインタフェースを指すとする。独立して稼働するシステム同士では、データ連携することで様々な処理を行う。例えば、基幹システム同士の連携では販売管理システムで入力された受注情報を、在庫管理システムや生産管理システムに連携することで、それぞれの業務を自動化できる。データ連携する先は必ずしも自社で運営するシステムにとどまらず、SaaSである場合もあれば、他社システムである場合もある。</p><p>本ガイドラインは、こうしたシステム間のデータ連携するためのI/F設計を説明する。システムI/Fにより、システムを外側から見た振る舞いを定義でき、またシステムあいだの依存関係（結合度）も変わってくる。適切なシステムI/Fを設計することで、システムの外部環境への変化に柔軟に対応し、システムの保守運用を最適化できる。</p><div class="img-bg-transparent"><p><img src="'+r+'" alt=""></p></div><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署／プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>本ガイドラインはシステム間のI/F全般を対象とし、以下の領域を含む。</p><ul><li>システム同士のデータ連携全般。<strong>特に基幹システム同士を指す</strong></li><li>自社内のシステム連携や、パートナー企業に対するシステム連携の両方</li><li>ファイル連携、Web API連携、メッセージング、DBリンクなど</li><li>情報系（OLAP）やデータ基盤へのデータ連携 の一部の手法</li></ul><p>逆に、以下の領域は含まない。</p><ul><li>業務画面、管理画面などUIによる入出力</li><li>帳票出力</li><li>印刷</li><li>メール、SMSなどのユーザー向けのメッセージ送信</li><li>データパッチなど、保守運用者によるシステムへの直接操作</li><li>パートナー企業向けのWeb API提供</li></ul><p>採用技術やシステム構成は以下を想定している。</p><ul><li>AWS、Google Cloud、Azureなどのクラウドサービスを用いての開発であること <ul><li>オンプレミスでの構築にも応用できる内容も多いと考えているが、ガイドライン作成時は強く念頭に置いていない</li></ul></li><li>各システムは独立したクラウドアカウントで構築されており、システム間のデータ連携は一種のクロスアカウント（クロスクラウド）でのやり取りとなること</li></ul><h2 id="用語定義" tabindex="-1">用語定義 <a class="header-anchor" href="#用語定義" aria-label="Permalink to &quot;用語定義&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">用語</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">I/F</td><td style="text-align:left;">インタフェースの略。本ガイドラインでは特に明記しない限り、対向システム向けのインタフェースのことを指す</td></tr><tr><td style="text-align:left;">対向システム</td><td style="text-align:left;">自システムから見て、データ連携先（元）のシステムのこと</td></tr><tr><td style="text-align:left;">データ連携</td><td style="text-align:left;">他システムに自システムのデータを共有すること。ファイル・Web APIなどフォーマット、プロトコルにも依存しない、抽象化された概念であるとする</td></tr><tr><td style="text-align:left;">ファイル連携</td><td style="text-align:left;">データ連携のうち、オブジェクトストレージ上などのファイルを共有することで行うこと</td></tr><tr><td style="text-align:left;">配信</td><td style="text-align:left;">データ連携のうち、データを提供する側。送信とも言う</td></tr><tr><td style="text-align:left;">集信</td><td style="text-align:left;">データ連携のうち、データを利用する側。受信とも言う</td></tr><tr><td style="text-align:left;">データ鮮度</td><td style="text-align:left;">連携先のデータをどれだけ速く、新しい状態で利用できるかのリアルタイム性のこと</td></tr></tbody></table><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、宮崎将太、武田大輝、村田靖拓、山口真明、澁川喜規、山田勇一</li><li><strong>レビュアー</strong>: 井上拓、椎名祐介</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.08.18 <a href="https://future-architect.github.io/articles/20250818a/" target="_blank" rel="noreferrer">I/F設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./if_guidelines.html">I/F設計ガイドライン</a></p></div>',20)])])}const p=e(s,[["render",d]]);export{g as __pageData,p as default};
